SELECT log_id, oper_class, obj_id, obj_desc, oper_type, oper_content, app_id AS "tenantId", oper_staff AS "updatorId", oper_date AS "updatedTime", (SELECT u.real_name FROM bt_user u WHERE u.user_id = a.oper_staff) AS "updatorName" FROM bt_oper_log a WHERE 1=1
AND a.app_id = #{query.tenantId}
AND a.oper_class = #{query.operClass}
AND a.obj_id = #{query.objId}
AND a.oper_type = #{query.operType}
ORDER BY oper_date DESC

SELECT obj_desc
FROM bt_oper_log
WHERE app_id = #{tenantId}
  AND log_id = #{logId}
